package org.xingmu.tv;
import org.json.*;import java.io.*;import java.util.*;import java.util.regex.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;
/** Resilient M3U import for a public subscription: skip unsupported rows, retain real groups. */
public final class SubscriptionParser {
 public static final class Result{public String json;public int entries,skipped;}
 public static Result parse(String text)throws IOException{return parse(text,"myIPTV","myiptv_");}
 public static Result parse(String text,String source,String prefix)throws IOException{if(text.length()>1_000_000)throw new IOException("列表超过 1 MB");Result result=new Result();Map<String,JSONObject> items=new LinkedHashMap<>();String title=null,group="其他",userAgent="XingmuTV/1.3";
  try{for(String raw:text.split("\\r?\\n")){String line=raw.trim();if(line.startsWith("#EXTINF:")){int separator=line.lastIndexOf(',');title=separator<0?"未命名频道":line.substring(separator+1).trim();Matcher match=Pattern.compile("group-title=\"([^\"]*)\"").matcher(line);group=match.find()?match.group(1):"其他";Matcher ua=Pattern.compile("http-user-agent=[\\x22]([^\\x22]*)[\\x22]").matcher(line);userAgent=ua.find()?ua.group(1):"XingmuTV/1.3";continue;}if(line.startsWith("#EXTVLCOPT:http-user-agent=")){userAgent=line.substring("#EXTVLCOPT:http-user-agent=".length()).trim();continue;}if(line.isEmpty()||line.startsWith("#"))continue;if(title==null)continue;
   String name=title;title=null;if(!CatalogParser.safeMediaUrl(line)){result.skipped++;continue;}String section=group.contains("点播")?"films":group.contains("国际")?"foreign":"domestic",country=section.equals("foreign")?"未分类":"中国";String key=group+"\n"+name;JSONObject item=items.get(key);if(item==null){if(items.size()>=3000){result.skipped++;continue;}byte[] hash=MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));StringBuilder id=new StringBuilder(prefix);for(int n=0;n<12;n++)id.append(String.format(Locale.ROOT,"%02x",hash[n]&255));item=new JSONObject().put("id",id.toString()).put("title",name).put("section",section).put("category",group).put("country",country).put("url",line).put("mode","stream").put("userAgent",userAgent).put("source",source).put("license",source+" 用户指定公开列表");items.put(key,item);}else if(!item.getString("url").equals(line)){JSONArray backups=item.optJSONArray("backupUrls");if(backups==null){backups=new JSONArray();item.put("backupUrls",backups);}boolean duplicate=false;for(int n=0;n<backups.length();n++)if(backups.getString(n).equals(line))duplicate=true;if(!duplicate&&backups.length()<7)backups.put(line);else if(!duplicate)result.skipped++;}
  }if(title!=null)result.skipped++;if(items.isEmpty())throw new IOException("订阅未包含支持的 HTTP/HTTPS 频道");JSONArray rows=new JSONArray();for(JSONObject item:items.values())rows.put(item);result.json=new JSONObject().put("authorized",true).put("items",rows).toString();CatalogParser.parse(result.json);result.entries=items.size();return result;}catch(IOException e){throw e;}catch(Exception e){throw new IOException("订阅格式错误",e);}
 }
}
